    Wallpaper { id: String },
    Gradient { angle: f64, stops: Vec<(Color, f64)> },
    Color { color: Color },
    Image { path: String },
}

impl Default for Background {
    fn default() -> Self {
        Background::Wallpaper { id: "aurora".into() }
    }
}

