    /// Direction the light comes from, degrees (90 = from above).
    pub angle: f64,
    pub distance: f64,
    pub blur: f64,
}

impl Default for Shadow {
    fn default() -> Self {
        Shadow { intensity: 0.75, angle: 90.0, distance: 25.0, blur: 20.0 }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
#[serde(default)]
pub struct Inset {
