#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn colour_round_trip() {
        let c = Color([1, 0xab, 0xff, 0x80]);
        assert_eq!(Color::parse(&c.hex()), Some(c));
        assert_eq!(Color::parse("#ffffff"), Some(Color::WHITE));
    }

    #[test]
    fn project_round_trips_through_json() {
        let mut p = Project::default();
        p.style.background = Background::Gradient { angle: 135.0, stops: vec![(Color::BLACK, 0.0), (Color::WHITE, 1.0)] };
        p.timeline.zooms.push(Zoom { mode: ZoomMode::Manual { target: v2(0.2, 0.3) }, ..Default::default() });
        let s = serde_json::to_string(&p).unwrap();
        let q: Project = serde_json::from_str(&s).unwrap();
        assert_eq!(p, q);
    }

    #[test]
    fn missing_fields_take_defaults() {
        let p: Project = serde_json::from_str(r#"{"name":"x","style":{"padding":3}}"#).unwrap();
        assert_eq!(p.style.padding, 3.0);
        assert_eq!(p.style.corner_radius, 12.0);
        assert_eq!(p.export.fps, ExportSettings::default().fps);
        assert_eq!(p.export.height, ExportSettings::NATIVE);
    }

    #[test]
    fn bitrate_formula() {
        let e = ExportSettings { height: 1080, fps: 60, ..Default::default() };
        assert_eq!(e.bitrate(1920, 1080, 10.0), (1920.0 * 1080.0 * 60.0 * 0.05) as u64);
        // Fit to 10 MB over 20 s: ~3.84 Mbit/s total minus audio.
        let t = ExportSettings { target_mb: Some(10), ..e };
        assert_eq!(t.bitrate(1920, 1080, 20.0), (10.0 * 8e6 * 0.96 / 20.0 - ExportSettings::AUDIO_BPS) as u64);
        assert!((t.estimate_mb(1920, 1080, 20.0) - 9.6).abs() < 0.01);
    }

    #[test]
    fn big_exports_switch_to_hevc() {
        let e = ExportSettings::default();
        assert_eq!(e.codec_for(3840, 2160), Codec::H264);
        assert_eq!(e.codec_for(4654, 3200), Codec::Hevc);
        assert_eq!(e.codec_for(2160, 3840), Codec::H264);
        assert_eq!(ExportSettings { codec: Codec::Hevc, ..e }.codec_for(1280, 720), Codec::Hevc);
    }
}

#!/usr/bin/env python3
"""Trigger and wait for a Greptile review of one GitHub PR revision."""

import argparse
import json
import re
import subprocess
import sys
import time
from datetime import datetime, timedelta, timezone
from pathlib import Path


DEFAULT_BOTS = ("greptile-apps[bot]", "greptile-apps-staging[bot]")
STUCK_CHECK_SECONDS = 1800


class ReviewError(RuntimeError):
    pass


def confidence(body):
    lines = []
    fence = None
    for line in body.splitlines():
        marker = re.match(r"^\s*(`{3,}|~{3,})", line)
        if marker:
            if fence is None:
                fence = marker[1]
            elif marker[1][0] == fence[0] and len(marker[1]) >= len(fence):
                fence = None
        elif fence is None:
            lines.append(line)
    text = re.sub(r"</?(?:h[1-6]|p|div)\b[^>]*>", "\n", "\n".join(lines))
    text = re.sub(r"<[^>]+>", " ", text).replace("*", "").replace("#", "").replace("_", "")
    scores = set(re.findall(r"^\s*confidence(?:\s+score)?\s*:?\s*([0-5])\s*/\s*5\s*$", text, re.I | re.M))
    return int(scores.pop()) if len(scores) == 1 else None


def reviewed_commit(body):
    match = re.search(r"last reviewed commit:[^\n]*?/commit/([0-9a-f]{40})\b", body, re.I)
    return match[1].lower() if match else None


def evaluate(attempt, current_head, checks, comments, reviews):
    """Return a fresh scored review, or a reason to keep waiting."""
    if current_head != attempt["head"]:
        raise ReviewError("PR head changed; start a new attempt for the new revision")
    triggered = attempt["triggered_at"]
    old_checks = {str(item["id"]): item for item in attempt["checks"]}
    fresh_checks = []
    for check in checks:
        if "greptile" not in check.get("name", "").lower():
            continue
        if check.get("head_sha") != current_head:
            continue
        old = old_checks.get(str(check["id"]))
        started = check.get("started_at") or ""
        if started < triggered:
            continue
        if old and started == old.get("started_at"):
            continue
        fresh_checks.append(check)

    # More than one run can exist for the same commit; use the newest attempt.
    latest = max(fresh_checks, key=lambda item: (item["started_at"], item["id"]), default=None)
    if latest and latest.get("status") != "completed":
        return {"status": "pending", "reason": "fresh check is still running"}
    if latest and latest.get("conclusion") in ("cancelled", "timed_out", "action_required", "skipped", "stale"):
        raise ReviewError(f"fresh check did not finish a review: {latest['conclusion']}")

    bots = attempt["bots"]
    old_reviews = {str(item["id"]): item for item in attempt["reviews"]}
    fresh_reviews = [
        item for item in reviews
        if item.get("user", {}).get("login") in bots
        and item.get("commit_id") == current_head
        and (item.get("submitted_at") or "") > triggered
        and item != old_reviews.get(str(item["id"]))
    ]
    candidates = []
    for review in fresh_reviews:
        if confidence(review.get("body") or "") is not None:
            candidates.append((review["submitted_at"], "review", review))

    skipped_notice = False
    old_comments = {str(item["id"]): item for item in attempt["comments"]}
    for comment in comments:
        if comment.get("user", {}).get("login") not in bots:
            continue
        if (comment.get("updated_at") or "") <= triggered:
            continue
        body = comment.get("body") or ""
        old = old_comments.get(str(comment["id"]))
        if old and body == old.get("body"):
            continue
        score = confidence(body)
        skipped = "too many files changed" in body.lower()
        skipped_notice = skipped_notice or (skipped and score is None)
        if score is None or skipped:
            continue
        commit = reviewed_commit(body)
        # A separate review cannot establish which revision this comment covers.
        if commit != current_head:
            continue
        candidates.append((comment["updated_at"], "comment", comment))

    if not candidates:
        # On the alternate route, an auto-review notice can precede the requested review.
        if skipped_notice and attempt.get("trigger") == "@greptile":
            raise ReviewError("Greptile skipped the review: too many files changed; start a new attempt with --trigger @greptile-apps")
        return {"status": "pending", "reason": "no fresh scored review tied to the current head"}
    updated, kind, result = max(candidates, key=lambda item: (item[0], item[2]["id"]))
    return {
        "status": "review_ready", "head": current_head,
        "score": confidence(result["body"]), "source": kind,
        "source_id": result["id"], "updated_at": updated,
        "body": result["body"], "url": result.get("html_url"),
        "check_id": latest["id"] if latest else None,
    }


class GitHub:
    def command(self, *args):
        result = subprocess.run(["gh", *args], capture_output=True, text=True, timeout=30)
        if result.returncode:
            raise ReviewError(result.stderr.strip() or "gh command failed")
        return json.loads(result.stdout)

    def pages(self, endpoint, key=None):
        pages = self.command("api", "--paginate", "--slurp", endpoint)
        return [item for page in pages for item in (page[key] if key else page)]

    def head(self, repo, pr):
        return self.command("api", f"repos/{repo}/pulls/{pr}")["head"]["sha"]

    def snapshot(self, repo, pr, head):
        return {
            "checks": self.pages(f"repos/{repo}/commits/{head}/check-runs?per_page=100&filter=all", "check_runs"),
            "comments": self.pages(f"repos/{repo}/issues/{pr}/comments?per_page=100"),
            "reviews": self.pages(f"repos/{repo}/pulls/{pr}/reviews?per_page=100"),
        }


def utc_now():
    return datetime.now(timezone.utc)


def started_before(check, cutoff):
    started = check.get("started_at")
    return bool(started) and datetime.fromisoformat(started.replace("Z", "+00:00")) < cutoff


def start(github, repo, pr, trigger, output, bots, stuck_after=STUCK_CHECK_SECONDS, ignored_checks=(), now=utc_now):
    # Reserve the path before posting so rerunning a command cannot post twice.
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open("x") as stream:
        json.dump({"status": "preparing", "repo": repo, "pr": pr}, stream)
    try:
        head = github.head(repo, pr)
        snapshot = github.snapshot(repo, pr, head)
        cutoff = now() - timedelta(seconds=stuck_after)
        running = [
            check for check in snapshot["checks"]
            if "greptile" in check.get("name", "").lower()
            and check.get("status") != "completed"
            and check["id"] not in ignored_checks
            and not started_before(check, cutoff)
        ]
        if running:
            check_id = running[0]["id"]
            # GitHub allows a null start time, and check runs have no creation time to age them by.
            raise ReviewError(
                f"Greptile check {check_id} is already running; let it finish before starting another. "
                f"Checks running longer than {stuck_after}s are treated as stuck. "
                f"If this check has no start time and is confirmed stuck, pass --ignore-check {check_id}."
            )
        if github.head(repo, pr) != head:
            raise ReviewError("PR head changed before the trigger")
    except BaseException:
        # Only release the reservation before posting the trigger.
        output.unlink()
        raise
    comment = github.command(
        "api", f"repos/{repo}/issues/{pr}/comments", "--method", "POST",
        "-f", f"body={trigger} review",
    )
    attempt = {
        "status": "triggered", "repo": repo, "pr": pr, "head": head, "trigger": trigger,
        "trigger_id": comment["id"], "triggered_at": comment["created_at"],
        "bots": list(bots), **snapshot,
    }
    output.write_text(json.dumps(attempt, indent=2) + "\n")
    return {key: value for key, value in attempt.items() if key not in snapshot}


def wait_for_review(github, attempt, timeout, interval, clock=time.monotonic, sleep=time.sleep):
    if attempt.get("status") != "triggered":
        raise ReviewError("attempt has no confirmed trigger; inspect the PR before retrying")
    deadline = clock() + timeout
    while True:
        head = github.head(attempt["repo"], attempt["pr"])
        if head != attempt["head"]:
            raise ReviewError("PR head changed; start a new attempt for the new revision")
        snapshot = github.snapshot(attempt["repo"], attempt["pr"], head)
        result = evaluate(attempt, github.head(attempt["repo"], attempt["pr"]), **snapshot)
        if result["status"] == "review_ready":
            return result
        remaining = deadline - clock()
        if remaining <= 0:
            raise ReviewError(f"review timed out: {result['reason']}")
        sleep(min(interval, remaining))


def positive(value):
    number = int(value)
    if number <= 0:
        raise argparse.ArgumentTypeError("must be a positive integer")
    return number


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    begin = commands.add_parser("start", help="snapshot state and post one review trigger")
    begin.add_argument("--repo", required=True, help="owner/repository")
    begin.add_argument("--pr", type=positive, required=True)
    begin.add_argument("--trigger", choices=("@greptile", "@greptile-apps"), default="@greptile")
    begin.add_argument("--output", type=Path, required=True)
    begin.add_argument("--bot", action="append", help="exact trusted login; repeat for multiple bots")
    begin.add_argument("--stuck-after", type=positive, default=STUCK_CHECK_SECONDS,
                       help="seconds after which a running Greptile check no longer blocks a new trigger")
    begin.add_argument("--ignore-check", type=positive, action="append", default=[],
                       help="check run ID confirmed stuck; repeat for several")
    wait = commands.add_parser("wait", help="read results without posting another trigger")
    wait.add_argument("attempt", type=Path)
    wait.add_argument("--timeout", type=positive, default=600)
    wait.add_argument("--interval", type=positive, default=10)
    args = parser.parse_args()
    github = GitHub()
    try:
        if args.command == "start":
            result = start(
                github, args.repo, args.pr, args.trigger, args.output, args.bot or DEFAULT_BOTS,
                args.stuck_after, args.ignore_check,
            )
        else:
            result = wait_for_review(github, json.loads(args.attempt.read_text()), args.timeout, args.interval)
        print(json.dumps(result, indent=2))
        return 0
    except (ReviewError, OSError, ValueError, subprocess.TimeoutExpired) as error:
        print(json.dumps({"status": "error", "message": str(error)}), file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

//! Export sharpness: at native size the screen is drawn pixel for pixel, and
//! downscaled exports filter fine detail instead of aliasing it.

use glide::engine::scene::Scene;
use glide::project::model::ExportSettings;
use glide::render::{Gpu, Image, Renderer, VideoFrame};

const W: u32 = 640;
const H: u32 = 400;

/// A 1-px black/white checkerboard: the finest detail a screen can show.
fn checker() -> Vec<u8> {
    let mut px = vec![0u8; (W * H * 4) as usize];
    for y in 0..H {
        for x in 0..W {
            let v = if (x + y) % 2 == 0 { 255 } else { 0 };
            let i = ((y * W + x) * 4) as usize;
            px[i..i + 4].copy_from_slice(&[v, v, v, 255]);
        }
    }
    px
}

/// Render the checkerboard as a bare screen (no padding, corners, shadow,
/// cursor or zoom) at an export height (0 = native).
fn render(height: u32) -> Image {
    let rec = glide::synth::recording(W, H, 1000.0);
    let mut project = glide::project::new_project("resample", &rec);
    let s = &mut project.style;
    s.padding = 0.0;
    s.corner_radius = 0.0;
    s.shadow.intensity = 0.0;
    s.cursor.hide = true;
    project.timeline.zooms.clear();
    let mut scene = Scene::new(project.clone(), &rec, 60.0);
    let (_, h) = scene.sizes.render_size(height);
    let frame = scene.frame(0.0, h as f64);
    let mut r = Renderer::new(Gpu::headless().unwrap());
    r.prepare(&project.style, &rec, None);
    let px = checker();
    r.set_screen(&VideoFrame { width: W, height: H, stride: (W * 4) as usize, bgra: &px });
    r.render_to_image(&frame, &project.style)
}

#[test]
fn native_export_is_pixel_exact() {
    let img = render(ExportSettings::NATIVE);
    assert_eq!((img.width, img.height), (W, H));
    let src = checker();
    let off = img.rgba.chunks(4).zip(src.chunks(4)).filter(|(a, b)| a[0].abs_diff(b[0]) > 1).count();
    assert_eq!(off, 0, "{off} pixels differ from the recording");
}

#[test]
fn downscaled_export_does_not_alias() {
    // At 0.68x (a 4K export of a 5K-wide design) each output pixel covers
    // ~1.5 checker texels: a proper filter gives near-flat mid-grey, while
    // bilinear sampling, as before, beats into black/white moire.
    let img = render(272);
    let w = img.width as usize;
    let inner = img.rgba.chunks(4).enumerate().filter(|(i, _)| {
        let (x, y) = (i % w, i / w);
        x >= 4 && y >= 4 && x + 4 < w && y + 4 < img.height as usize
    });
    let (lo, hi) = inner.fold((255u8, 0u8), |(lo, hi), (_, p)| (lo.min(p[0]), hi.max(p[0])));
    assert!(hi - lo <= 48 && lo >= 96 && hi <= 160, "grey range {lo}..{hi}");
}

// A plain app window from another process (osascript) for the selftest's
// audio checks: an app ScreenCaptureKit can hear, that isn't Glide.
// Usage: osascript -l JavaScript test-window.js SECONDS [SOUND DELAY]
// shows the window for SECONDS and, given SOUND, plays it after DELAY s.
ObjC.import('Cocoa');
ObjC.import('AVFoundation');
function run(argv) {
  var secs = parseFloat(argv[0] || '30');
  var app = $.NSApplication.sharedApplication;
  app.setActivationPolicy($.NSApplicationActivationPolicyAccessory);
  var w = $.NSWindow.alloc.initWithContentRectStyleMaskBackingDefer($.NSMakeRect(40, 40, 360, 220), 1, $.NSBackingStoreBuffered, false);
  w.title = argv[1] ? 'Glide audio test (sound)' : 'Glide audio test';
  w.backgroundColor = $.NSColor.systemTealColor;
  w.orderFrontRegardless;
  var loop = $.NSRunLoop.currentRunLoop;
  var until = function (s) { loop.runUntilDate($.NSDate.dateWithTimeIntervalSinceNow(s)); };
  if (argv[1]) {
    var delay = parseFloat(argv[2] || '0');
    until(delay);
    var player = $.AVAudioPlayer.alloc.initWithContentsOfURLError($.NSURL.fileURLWithPath(argv[1]), null);
    player.play;
    until(Math.max(secs - delay, 0));
  } else {
    until(secs);
  }
}

//! The Background settings (wallpaper, gradient, colour, image, blur) and
//! the padding, roundness and shadow that frame them change the editor's
//! canvas as soon as they're edited, and the export draws the same thing.
//! Each check renders the preview, reads its pixels back and compares.

use std::path::{Path, PathBuf};
use std::sync::atomic::AtomicBool;

use glide::app::editor::Editor;
use glide::export::{self, Job, Source};
use glide::project::model::{Aspect, Background, Color, ExportSettings, Quality, Style};
use glide::render::bgcheck::{self, Region};
use glide::render::{Gpu, Image};

const SIZE: (u32, u32) = (640, 400);

/// A synthetic recording opened in the editor, with its auto zooms removed
/// so the background stays in view.
fn editor(name: &str) -> (PathBuf, Editor) {
    let dir = std::env::temp_dir().join(format!("glide-bg-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("Background.glide");
    glide::synth::write_package(&path, 1.0, 1280, 800).unwrap();
    let mut ed = Editor::open(&path, Gpu::headless().unwrap()).unwrap();
    let mut d = ed.project.clone();
    d.timeline.zooms.clear();
    ed.commit(d);
    (dir, ed)
}

fn draw(ed: &mut Editor, size: (u32, u32)) -> Image {
    ed.preview.draw(0.0, size);
    let (width, height, rgba) = ed.preview.read_pixels().expect("preview pixels");
    Image { width, height, rgba }
}

/// Set the style the way the inspector does (on a draft, then commit) and
/// return the canvas the preview shows afterwards.
fn show(ed: &mut Editor, style: &Style) -> Image {
    let mut d = ed.project.clone();
    d.style = style.clone();
    ed.commit(d);
    draw(ed, SIZE)
}

#[test]
fn every_background_setting_changes_the_canvas() {
    let (dir, mut ed) = editor("live");
    assert!(ed.project.style.padding > 0.0, "the background shows by default");
    let image = dir.join("checker.png");
    bgcheck::checkerboard(&image).unwrap();
    let style = ed.project.style.clone();
    let outcomes = bgcheck::run(&style, &image.to_string_lossy(), |s| Ok(show(&mut ed, s))).unwrap();
    let failed: Vec<_> = outcomes.iter().filter(|o| !o.ok()).collect();
    assert!(failed.is_empty(), "no visible change for: {failed:#?}");
    assert_eq!(outcomes.len(), bgcheck::steps("").len());

    // A colour is drawn as that colour.
    let mut s = ed.project.style.clone();
    s.background = Background::Color { color: Color::rgb(52, 120, 246) };
    let c = show(&mut ed, &s);
    assert_eq!(&c.rgba[..3], &[52, 120, 246], "top-left pixel");

    drop(ed);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn background_edits_at_zero_padding_bring_it_into_view() {
    let (dir, mut ed) = editor("reveal");
    // Edge to edge, nothing but the recording shows.
    let mut s = ed.project.style.clone();
    s.padding = 0.0;
    s.corner_radius = 0.0;
    let flat = show(&mut ed, &s);
    // A background change alone is invisible at 0 %…
    s.background = Background::Color { color: Color::rgb(220, 40, 40) };
    let hidden = show(&mut ed, &s);
    assert!(bgcheck::changed(&hidden, &flat, Region::Border, 30) < 0.01, "nothing to see at 0 % padding");
    // …so the inspector adds padding along with it.
    let before = s.clone();
    s.background = Background::Color { color: Color::rgb(40, 200, 90) };
    assert!(s.reveal_background(&before));
    assert_eq!(s.padding, Style::REVEAL_PADDING);
    let shown = show(&mut ed, &s);
    let c = bgcheck::changed(&shown, &hidden, Region::Border, 30);
    assert!(c > 0.9, "revealed background: {:.0}% changed", c * 100.0);
    // Padding edits themselves are left alone.
    let before = s.clone();
    s.padding = 0.0;
    assert!(!s.reveal_background(&before));

    drop(ed);
    let _ = std::fs::remove_dir_all(&dir);
}

/// Export the first frame of the project and decode it back.
fn export_frame(ed: &Editor, dir: &Path, name: &str) -> Image {
    let settings = ExportSettings { height: 400, fps: 10, quality: Quality::Studio, ..Default::default() };
    let output = dir.join(format!("{name}.mp4"));
    let job = Job { project: ed.project.clone(), recording: ed.rec.clone(), source: Source::Package(ed.package.root.clone()), settings, output: output.clone() };
    export::run(&job, &mut |_| {}, &AtomicBool::new(false)).unwrap();
    let mut src = glide::media::FrameSource::open(&output).unwrap();
    let frame = src.frame_at(0.0).unwrap();
    frame.with_bgra(|v| {
        let mut rgba = Vec::with_capacity((v.width * v.height * 4) as usize);
        for row in v.bgra.chunks(v.stride).take(v.height as usize) {
            for p in row[..(v.width * 4) as usize].chunks_exact(4) {
                rgba.extend_from_slice(&[p[2], p[1], p[0], 255]);
            }
        }
        Image { width: v.width, height: v.height, rgba }
    })
}

fn mean_abs_diff(a: &Image, b: &Image) -> f64 {
    assert_eq!((a.width, a.height), (b.width, b.height));
    let sum: u64 = a.rgba.chunks_exact(4).zip(b.rgba.chunks_exact(4)).map(|(a, b)| (0..3).map(|c| a[c].abs_diff(b[c]) as u64).sum::<u64>()).sum();
    sum as f64 / (a.width * a.height * 3) as f64
}

#[test]
fn export_draws_the_background_the_preview_shows() {
    let (dir, mut ed) = editor("export");
    let styles: [(&str, fn(&mut Style)); 3] = [
        ("wallpaper", |s| {
            s.background = Background::Wallpaper { id: "ocean".into() };
            s.background_blur = 20.0;
        }),
        ("gradient", |s| {
            s.background = Background::Gradient { angle: 90.0, stops: vec![(Color::rgb(255, 110, 196), 0.0), (Color::rgb(120, 115, 245), 1.0)] };
            s.background_blur = 0.0;
            s.padding = 20.0;
            s.corner_radius = 30.0;
        }),
        ("colour", |s| {
            s.background = Background::Color { color: Color::rgb(30, 140, 90) };
            s.shadow.intensity = 1.0;
        }),
    ];
    let mut exported: Vec<Image> = vec![];
    for (name, f) in &styles {
        let mut s = ed.project.style.clone();
        f(&mut s);
        // A fixed frame, so the exports line up pixel for pixel.
        s.aspect = Aspect::Ratio { w: 16, h: 9 };
        show(&mut ed, &s);
        let video = export_frame(&ed, &dir, name);
        let preview = draw(&mut ed, (video.width, video.height));
        let diff = mean_abs_diff(&preview, &video);
        assert!(diff < 6.0, "{name}: export differs from the preview by {diff:.1} per channel");
        for (other, prev) in exported.iter().enumerate() {
            let c = bgcheck::changed(&video, prev, Region::Border, 30);
            assert!(c > 0.5, "{name} vs {}: only {:.0}% of the exported background differs", styles[other].0, c * 100.0);
        }
        exported.push(video);
    }

    drop(ed);
    let _ = std::fs::remove_dir_all(&dir);
}

//! A recording's audio reaches the editor and the export: track levels are
//! measured (and silence explained), the playback mix follows mutes while
//! the project is open, and the exported MP4 carries the sound. Playing
//! through the speakers is checked by the GUI play-test in
//! scripts/selftest.sh.

use std::sync::atomic::AtomicBool;
use std::time::{Duration, Instant};

use glide::app::editor::{Editor, TrackPeaks, silence_note};
use glide::export::{self, Job, Source};
use glide::project::model::{ExportSettings, Quality};
use glide::render::Gpu;

fn package(name: &str, tone: Option<f64>) -> (std::path::PathBuf, std::path::PathBuf) {
    let dir = std::env::temp_dir().join(format!("glide-audio-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("Audio.glide");
    glide::synth::write_package(&path, 2.0, 640, 400).unwrap();
    if let Some(hz) = tone {
        glide::synth::add_tone(&path, hz).unwrap();
    }
    (dir, path)
}

fn wait(mut done: impl FnMut() -> bool) {
    let t = Instant::now();
    while !done() {
        assert!(t.elapsed() < Duration::from_secs(20), "timed out");
        std::thread::sleep(Duration::from_millis(20));
    }
}

fn peaks(ed: &Editor) -> TrackPeaks {
    let mut p = None;
    wait(|| {
        p = *ed.peaks.lock().unwrap();
        p.is_some()
    });
    p.unwrap()
}

#[test]
fn track_levels_explain_a_silent_recording() {
    let (dir, path) = package("levels", Some(880.0));
    let ed = Editor::open(&path, Gpu::headless().unwrap()).unwrap();
    let p = peaks(&ed);
    assert!(p.system.is_some_and(|v| (v - 0.1).abs() < 0.01), "{p:?}");
    assert!(p.mic.is_none());
    assert!(!TrackPeaks::silent(p.system));
    drop(ed);

    // Same recording with a silent system track and no microphone.
    let (_, mut rec) = glide::project::Package::new(&path).load().unwrap();
    glide::app::player::write_wav(&glide::project::Package::new(&path).rec("system.wav"), &vec![[0.0; 2]; 96_000]).unwrap();
    let ed = Editor::open(&path, Gpu::headless().unwrap()).unwrap();
    let p = peaks(&ed);
    assert!(TrackPeaks::silent(p.system), "{p:?}");
    assert!(silence_note(&ed.rec, p).contains("microphone was off"));
    rec.meta.system_audio = None;
    assert!(silence_note(&rec, p).contains("no audio"));
    drop(ed);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn playback_mix_follows_mutes_while_open() {
    let (dir, path) = package("mix", Some(880.0));
    let mut ed = Editor::open(&path, Gpu::headless().unwrap()).unwrap();
    let settle = |ed: &mut Editor| {
        wait(|| {
            ed.tick();
            !ed.audio.mixing()
        })
    };
    settle(&mut ed);
    assert!(ed.audio.has_audio(), "the tone is mixed for playback");
    let mut d = ed.project.clone();
    d.style.audio.mute_system = true;
    ed.commit(d);
    settle(&mut ed);
    assert!(!ed.audio.has_audio(), "muted: nothing to play");
    let mut d = ed.project.clone();
    d.style.audio.mute_system = false;
    d.style.audio.volume = 0.5;
    ed.commit(d);
    settle(&mut ed);
    assert!(ed.audio.has_audio(), "unmuted again");
    drop(ed);
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn export_carries_the_recorded_sound() {
    let (dir, path) = package("export", Some(880.0));
    let pkg = glide::project::Package::new(&path);
    let (project, recording) = pkg.load().unwrap();
    let output = dir.join("out.mp4");
    let settings = ExportSettings { height: 240, fps: 10, quality: Quality::Web, ..Default::default() };
    let job = Job { project, recording, source: Source::Package(path.clone()), settings, output: output.clone() };
    export::run(&job, &mut |_| {}, &AtomicBool::new(false)).unwrap();
    let audio = glide::media::read_audio(&output, 0).expect("the export has an audio track");
    let level = glide::audiocheck::analyze(&audio, 880.0);
    assert!(level.tone_seconds > 1.8, "{level:?}");
    assert!((level.tone_db + 23.0).abs() < 1.5, "{level:?}");
    let _ = std::fs::remove_dir_all(&dir);
}

//! Headless UI smoke test: drive the start view (recording setup) and every
//! editor panel through egui frames (no window), including selections,
//! playback, the export sheet and the title-bar controls, to catch panics
//! and layout loops without needing a display.

use std::time::Duration;

use glide::app::editor::{Editor, Selection, Tab};
use glide::app::home::{self, Devices, Settings, Thumbs};
use glide::render::Gpu;

fn frame(ctx: &egui::Context, t: f64, f: impl FnMut(&mut egui::Ui)) {
    let input = egui::RawInput {
        screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(1320.0, 840.0))),
        time: Some(t),
        ..Default::default()
    };
    let _ = ctx.run_ui(input, f);
}

#[test]
fn editor_and_home_render_every_panel() {
    let dir = std::env::temp_dir().join(format!("glide-ui-smoke-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("Smoke.glide");
    glide::synth::write_package(&path, 3.0, 1280, 800).unwrap();

    let gpu = Gpu::headless().unwrap();
    let mut renderer = egui_wgpu::Renderer::new(&gpu.device, wgpu::TextureFormat::Bgra8Unorm, egui_wgpu::RendererOptions::default());
    let ctx = egui::Context::default();
    glide::app::theme::apply(&ctx);

    let mut ed = Editor::open(&path, gpu).unwrap();
    let mut t = 0.0;
    let mut settings = Settings { projects_dir: Some(dir.clone()), ..Settings::default() };
    let mut devices = Devices::default();
    let mut thumbs = Thumbs::default();
    let projects = home::scan_projects(&dir);
    assert_eq!(projects.len(), 1);
    // The editor's frame: its title bar draws Back, the title (recents) and
    // the record controls from the app's settings.
    let mut actions = vec![];
    let mut editor_frame = |ed: &mut Editor, t: f64| {
        frame(&ctx, t, |ui| {
            let mut chrome = home::Chrome { settings: &mut settings, devices: &mut devices, projects: &projects, thumbs: &mut thumbs, action: home::Action::None };
            ed.ui(ui, &mut renderer, &mut chrome);
            if !matches!(chrome.action, home::Action::None) {
                actions.push(format!("{:?}", std::mem::discriminant(&chrome.action)));
            }
        })
    };
    for (tab, _) in Tab::ALL {
        ed.tab = tab;
        for _ in 0..2 {
            t += 0.016;
            editor_frame(&mut ed, t);
        }
    }
    // Selections show their own inspector panels.
    let zoom = ed.project.timeline.zooms.first().map(|z| z.id);
    let slice = ed.project.timeline.slices[0].id;
    for sel in [Selection::Slice(slice), zoom.map_or(Selection::None, Selection::Zoom)] {
        ed.selection = sel;
        t += 0.016;
        editor_frame(&mut ed, t);
    }
    // Edits: split, add a zoom, undo/redo.
    ed.seek(1500.0);
    ed.split();
    assert_eq!(ed.project.timeline.slices.len(), 2);
    let zooms = ed.project.timeline.zooms.len();
    ed.seek(400.0);
    ed.add_zoom();
    assert!(ed.project.timeline.zooms.len() >= zooms);
    ed.undo();
    ed.undo();
    assert_eq!(ed.project.timeline.slices.len(), 1);
    ed.redo();
    assert_eq!(ed.project.timeline.slices.len(), 2);

    // Playback advances the playhead.
    ed.seek(0.0);
    ed.toggle_play();
    std::thread::sleep(Duration::from_millis(120));
    assert!(ed.tick());
    assert!(ed.playhead > 50.0, "playhead {}", ed.playhead);
    ed.toggle_play();

    // The export sheet renders.
    ed.export.open = true;
    t += 0.016;
    editor_frame(&mut ed, t);
    ed.export.open = false;

    // A blur over the first sidebar item: the synthetic UI moves the
    // selection away at 1.5 s, so "data may be visible" is flagged there and
    // cutting it removes that part of the recording.
    let (ws, hs) = (1280.0 * 1080.0 / 800.0, 1080.0);
    ed.edit(|p| {
        let id = p.timeline.new_id();
        let rect = glide::engine::geom::Rect::new(15.0 / ws, 75.0 / hs, 210.0 / ws, 32.0 / hs);
        p.timeline.masks.push(glide::project::model::Mask { id, start: 200.0, end: 2900.0, rect, ..Default::default() });
    });
    let t0 = std::time::Instant::now();
    ed.tick();
    while (ed.mask_watch.busy() || ed.mask_watch.found.is_empty()) && t0.elapsed() < Duration::from_secs(30) {
        std::thread::sleep(Duration::from_millis(50));
        ed.tick();
    }
    let found = ed.mask_watch.found.clone();
    assert_eq!(found.len(), 1, "{found:?}");
    assert!((found[0].start - 1500.0).abs() <= 100.0 && found[0].end >= 2800.0, "{found:?}");
    assert!(glide::app::timeline::extra_height(&ed) > 0.0);
    t += 0.016;
    editor_frame(&mut ed, t);
    ed.cut_exposure(found[0]);
    assert!(ed.project.timeline.slices.iter().all(|s| s.end <= found[0].start || s.start >= found[0].end), "{:?}", ed.project.timeline.slices);
    assert_eq!(glide::app::timeline::extra_height(&ed), 0.0);
    t += 0.016;
    editor_frame(&mut ed, t);
    ed.save();
    drop(editor_frame);
    assert!(actions.is_empty(), "no title-bar button was pressed: {actions:?}");
    let root = ed.package.root.clone();

    // Start view (no recording open) with this folder as the library, every
    // source, the recents popover and the permission note.
    // With and without live preview textures (source and camera) and meters.
    let tex = ctx.load_texture("live", egui::ColorImage::new([64, 40], vec![egui::Color32::DARK_GRAY; 64 * 40]), egui::TextureOptions::LINEAR);
    for (source, live) in [
        (home::SourceKind::Display, Some((tex.id(), tex.size_vec2()))),
        (home::SourceKind::Window, None),
        (home::SourceKind::Area, Some((tex.id(), tex.size_vec2()))),
        (home::SourceKind::Device, None),
    ] {
        settings.source = source;
        settings.camera = live.is_some();
        let live = home::LiveView {
            screen: live,
            camera: live,
            system_level: live.map(|_| 0.4),
            mic_level: None,
            note: live.is_none().then(|| "Choose a window to see it here.".into()),
            covered: None,
        };
        for _ in 0..2 {
            t += 0.016;
            frame(&ctx, t, |ui| {
                let a = home::start_view(ui, &mut settings, &mut devices, &projects, &mut thumbs, Some("permission note"), &live);
                assert!(matches!(a, home::Action::None));
            });
        }
    }
    t += 0.016;
    frame(&ctx, t, |ui| {
        let a = home::recents(ui, &projects, &mut thumbs, Some(&root), &dir);
        assert!(matches!(a, home::Action::None));
    });
    let _ = std::fs::remove_dir_all(&dir);
}

//! Inspector: style sections, and properties of the selected timeline item.

use egui::{Color32, CornerRadius, RichText, Sense, Stroke, Ui, vec2};

use super::editor::{Deferred, Editor, Selection, Tab};
use super::theme::{self, pal};
use super::widgets::{self, caption, row, section, segmented, slider, toggle_row};
use crate::engine::geom::v2;
use crate::engine::spring::SpringConfig;
use crate::project::model::*;
use crate::render::art::WALLPAPERS;

const GRADIENTS: [(&str, [u8; 3], [u8; 3], f64); 6] = [
    ("Dusk", [255, 120, 80], [130, 70, 220], 135.0),
    ("Ocean", [40, 160, 255], [20, 220, 190], 120.0),
    ("Candy", [255, 110, 196], [120, 115, 245], 90.0),
    ("Forest", [30, 120, 90], [150, 210, 120], 160.0),
    ("Night", [20, 24, 40], [70, 60, 120], 180.0),
    ("Paper", [245, 245, 240], [220, 220, 215], 180.0),
];

pub fn ui(ui: &mut Ui, ed: &mut Editor) {
    egui::ScrollArea::vertical().auto_shrink(false).show(ui, |ui| {
        let mut draft = ed.project.clone();
        match ed.selection {
            Selection::Zoom(id) => zoom_panel(ui, ed, &mut draft, id),
            Selection::Slice(id) => slice_panel(ui, &mut draft, id),
            Selection::Layout(id) => layout_panel(ui, &mut draft, id),
            Selection::Mask(id) => mask_panel(ui, ed, &mut draft, id),
            Selection::None => {
                tabs(ui, &mut ed.tab);
                match ed.tab {
                    Tab::Background => background(ui, ed, &mut draft),
                    Tab::Cursor => cursor(ui, &mut draft, ed.rec.mouse.is_empty()),
                    Tab::Camera => camera(ui, &mut draft, ed.rec.meta.camera.is_some()),
                    Tab::Captions => captions(ui, ed, &mut draft),
                    Tab::Audio => audio(ui, ed, &mut draft),
                    Tab::Shortcuts => shortcuts(ui, &mut draft, ed.rec.keys.len()),
                    Tab::Animation => animation(ui, ed, &mut draft),
                }
            }
        }
        if ui.input(|i| i.pointer.any_released()) {
            // End of a drag: the next change starts a new undo step.
        }
        ed.commit(draft);
        // Actions that edit the project themselves run after the draft lands.
        match ed.deferred.take() {
            Some(Deferred::StartVoice) => ed.start_voiceover(),
            Some(Deferred::StopVoice) => ed.stop_voiceover(),
            None => {}
        }
    });
}

fn tabs(ui: &mut Ui, tab: &mut Tab) {
    let p = pal(ui);
    ui.horizontal_wrapped(|ui| {
        ui.spacing_mut().item_spacing = vec2(4.0, 4.0);
        for (t, label) in Tab::ALL {
            let sel = *tab == t;
            let b = egui::Button::new(RichText::new(label).size(12.0).color(if sel { Color32::WHITE } else { p.text }))
                .fill(if sel { theme::accent() } else { p.control })
                .stroke(if sel { Stroke::NONE } else { Stroke::new(0.5, p.control_border) })
                .corner_radius(CornerRadius::same(12));
            if ui.add(b).clicked() {
                *tab = t;
            }
        }
    });
    ui.add_space(4.0);
    ui.separator();
}

/// Ask for a PNG or JPEG, check it decodes, and copy it into the package.
fn choose_image(ed: &mut Editor) -> Option<String> {
    let f = rfd::FileDialog::new().add_filter("Images", &["png", "jpg", "jpeg"]).pick_file()?;
    match crate::render::Image::from_png(&f).and_then(|_| ed.package.import_asset(&f, "background")) {
        Ok(rel) => Some(rel),
        Err(e) => {
            ed.status = Some(format!("Couldn't use that image: {e:#}"));
            None
        }
    }
}

fn swatch(ui: &mut Ui, size: egui::Vec2, selected: bool, paint: impl FnOnce(&egui::Painter, egui::Rect)) -> bool {
    let (rect, resp) = ui.allocate_exact_size(size, Sense::click());
    paint(ui.painter(), rect);
    let stroke = if selected { Stroke::new(2.5, theme::accent()) } else { Stroke::new(1.0, pal(ui).control_border) };
    ui.painter().rect_stroke(rect, CornerRadius::same(6), stroke, egui::StrokeKind::Outside);
    resp.clicked()
}

fn background(ui: &mut Ui, ed: &mut Editor, d: &mut Project) {
    let before = d.style.clone();
    let s = &mut d.style;
    section(ui, "Background", |ui| {
        if s.padding <= 0.0 && s.device == DeviceFrame::None {
            caption(ui, "Hidden at 0 % padding. Pick a background (or raise Padding) to show it.");
        }
        #[derive(Clone, Copy, PartialEq)]
        enum K {
            Wall,
            Grad,
            Col,
            Img,
        }
        let mut k = match s.background {
            Background::Wallpaper { .. } => K::Wall,
            Background::Gradient { .. } => K::Grad,
            Background::Color { .. } => K::Col,
            Background::Image { .. } => K::Img,
        };
        if segmented(ui, &mut k, &[(K::Wall, "Wallpaper"), (K::Grad, "Gradient"), (K::Col, "Color"), (K::Img, "Image")]) {
            s.background = match k {
                K::Wall => Background::Wallpaper { id: "aurora".into() },
                K::Grad => Background::Gradient { angle: 135.0, stops: vec![(Color::rgb(255, 120, 80), 0.0), (Color::rgb(130, 70, 220), 1.0)] },
                K::Col => Background::Color { color: Color::rgb(52, 120, 246) },
                // Ask for the image straight away; cancelling keeps the old background.
                K::Img => choose_image(ed).map_or_else(|| s.background.clone(), |path| Background::Image { path }),
            };
        }
        ui.add_space(6.0);
        match &mut s.background {
            Background::Wallpaper { id } => {
                let thumbs = ed.thumbs.get_or_insert_with(|| {
                    WALLPAPERS
                        .iter()
                        .map(|w| {
                            let img = crate::render::art::wallpaper(w.0, 96, 60);
                            let ci = egui::ColorImage::from_rgba_unmultiplied([96, 60], &img.rgba);
                            ui.ctx().load_texture(format!("wall-{}", w.0), ci, egui::TextureOptions::LINEAR)
                        })
                        .collect()
                });
                ui.horizontal_wrapped(|ui| {
                    ui.spacing_mut().item_spacing = vec2(6.0, 6.0);
                    for (i, w) in WALLPAPERS.iter().enumerate() {
                        let tex = thumbs[i].id();
                        let clicked = swatch(ui, vec2(52.0, 34.0), *id == w.0, |p, r| {
                            p.image(tex, r, egui::Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)), Color32::WHITE);
                        });
                        if clicked {
                            *id = w.0.into();
                        }
                    }
                });
            }
            Background::Gradient { angle, stops } => {
                ui.horizontal_wrapped(|ui| {
                    ui.spacing_mut().item_spacing = vec2(6.0, 6.0);
                    for (_, a, b, ang) in GRADIENTS {
                        let (ca, cb) = (Color32::from_rgb(a[0], a[1], a[2]), Color32::from_rgb(b[0], b[1], b[2]));
                        let sel = stops.first().map(|s| s.0) == Some(Color::rgb(a[0], a[1], a[2]));
                        if swatch(ui, vec2(34.0, 34.0), sel, |p, r| {
                            let mut mesh = egui::Mesh::default();
                            mesh.colored_vertex(r.left_top(), ca);
                            mesh.colored_vertex(r.right_top(), widgets::lerp_color(ca, cb, 0.5));
                            mesh.colored_vertex(r.right_bottom(), cb);
                            mesh.colored_vertex(r.left_bottom(), widgets::lerp_color(ca, cb, 0.5));
                            mesh.add_triangle(0, 1, 2);
                            mesh.add_triangle(0, 2, 3);
                            p.add(mesh);
                        }) {
                            *angle = ang;
                            *stops = vec![(Color::rgb(a[0], a[1], a[2]), 0.0), (Color::rgb(b[0], b[1], b[2]), 1.0)];
                        }
                    }
                });
                slider(ui, "Angle", angle, 0.0..=360.0, "°");
                for (i, (c, _)) in stops.iter_mut().enumerate() {
                    row(ui, if i == 0 { "From" } else { "To" }, |ui| {
                        widgets::color_edit(ui, c);
                    });
                }
            }
            Background::Color { color } => {
                row(ui, "Color", |ui| {
                    widgets::color_edit(ui, color);
                });
            }
            Background::Image { path } => {
                ui.horizontal(|ui| {
                    if ui.button("Choose image…").clicked()
                        && let Some(rel) = choose_image(ed)
                    {
                        *path = rel;
                    }
                    if ui.button("Desktop wallpaper").on_hover_text("Use your current macOS desktop picture").clicked() {
                        let tmp = std::env::temp_dir().join(format!("glide-wallpaper-{}.png", std::process::id()));
                        match super::macos::save_desktop_wallpaper(&tmp).and_then(|_| ed.package.import_asset(&tmp, "wallpaper")) {
                            Ok(rel) => *path = rel,
                            Err(e) => ed.status = Some(format!("Couldn't use the desktop wallpaper: {e:#}")),
                        }
                        let _ = std::fs::remove_file(&tmp);
                    }
                });
                caption(ui, &std::path::Path::new(path.as_str()).file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_else(|| "No image".into()));
            }
        }
        // Blurring a flat colour or a gradient changes nothing.
        if matches!(s.background, Background::Wallpaper { .. } | Background::Image { .. }) {
            slider(ui, "Blur", &mut s.background_blur, 0.0..=60.0, " px");
        }
    });
    section(ui, "Frame", |ui| {
        slider(ui, "Padding", &mut s.padding, 0.0..=40.0, "%");
        row(ui, "Device", |ui| {
            use crate::project::model::DeviceFrame as D;
            segmented(ui, &mut s.device, &[(D::None, "None"), (D::Laptop, "Laptop"), (D::Phone, "Phone"), (D::Tablet, "Tablet")]);
        });
        if s.device == DeviceFrame::None {
            slider(ui, "Roundness", &mut s.corner_radius, 0.0..=60.0, " px");
        }
        slider(ui, "Inset", &mut s.inset.padding, 0.0..=60.0, " px");
        if s.inset.padding > 0.0 {
            row(ui, "Inset color", |ui| {
                widgets::color_edit(ui, &mut s.inset.color);
            });
            slider(ui, "Inset opacity", &mut s.inset.alpha, 0.0..=1.0, "");
        }
        row(ui, "Aspect ratio", |ui| {
            let label = Aspect::PRESETS.iter().find(|(_, a)| *a == s.aspect).map_or("Custom", |(n, _)| n);
            egui::ComboBox::from_id_salt("aspect").selected_text(label).show_ui(ui, |ui| {
                for (n, a) in Aspect::PRESETS {
                    ui.selectable_value(&mut s.aspect, a, n);
                }
            });
        });
    });
    section(ui, "Shadow", |ui| {
        slider(ui, "Intensity", &mut s.shadow.intensity, 0.0..=1.0, "");
        slider(ui, "Angle", &mut s.shadow.angle, 0.0..=360.0, "°");
        slider(ui, "Distance", &mut s.shadow.distance, 0.0..=100.0, " px");
        slider(ui, "Blur", &mut s.shadow.blur, 0.0..=100.0, " px");
    });
    if s.reveal_background(&before) {
        ed.status = Some(format!("Padding was 0 %, which hides the background, so it's now {} %.", Style::REVEAL_PADDING));
    }
    section(ui, "Crop", |ui| {
        let c = &mut s.crop;
        let (mut l, mut t, mut r, mut b) = (c.x, c.y, 1.0 - c.x - c.w, 1.0 - c.y - c.h);
        let mut ch = false;
        ch |= slider(ui, "Left", &mut l, 0.0..=0.45, "");
        ch |= slider(ui, "Right", &mut r, 0.0..=0.45, "");
        ch |= slider(ui, "Top", &mut t, 0.0..=0.45, "");
        ch |= slider(ui, "Bottom", &mut b, 0.0..=0.45, "");
        if ch {
            *c = crate::engine::geom::Rect::new(l, t, (1.0 - l - r).max(0.1), (1.0 - t - b).max(0.1));
        }
        if ui.small_button("Reset crop").clicked() {
            *c = crate::engine::geom::Rect::UNIT;
        }
    });
}

fn spring_picker(ui: &mut Ui, label: &str, cfg: &mut Option<SpringConfig>, presets: &[(&str, Option<SpringConfig>)]) {
    ui.label(label);
    ui.horizontal_wrapped(|ui| {
        for (name, p) in presets {
            let sel = cfg == p;
            if ui.selectable_label(sel, *name).clicked() {
                *cfg = *p;
            }
        }
    });
    if let Some(c) = cfg {
        egui::CollapsingHeader::new("Customize").id_salt(label).show(ui, |ui| {
            caption(ui, "Motion follows Newtonian physics: a mass on a spring.");
            slider(ui, "Rigidity", &mut c.stiffness, 5.0..=1500.0, "");
            slider(ui, "Smoothness", &mut c.damping, 5.0..=200.0, "");
            slider(ui, "Momentum", &mut c.mass, 0.1..=15.0, "");
        });
    }
}

fn cursor(ui: &mut Ui, d: &mut Project, no_data: bool) {
    let c = &mut d.style.cursor;
    if no_data {
        caption(ui, "This recording has no cursor data.");
    }
    section(ui, "Cursor", |ui| {
        toggle_row(ui, "Hide cursor", &mut c.hide);
        slider(ui, "Size", &mut c.size, 0.5..=4.0, "×");
        row(ui, "Style", |ui| {
            segmented(ui, &mut c.skin, &[(CursorSkin::Touch, "Touch"), (CursorSkin::Vector, "Vector"), (CursorSkin::System, "System")]);
        });
    });
    section(ui, "Movement", |ui| {
        spring_picker(
            ui,
            "Smoothing",
            &mut c.smoothing,
            &[
                ("Smooth", Some(SpringConfig::CURSOR_SMOOTH)),
                ("Medium", Some(SpringConfig::CURSOR_MEDIUM)),
                ("Rapid", Some(SpringConfig::CURSOR_RAPID)),
                ("Off", None),
            ],
        );
        slider(ui, "Tilt", &mut c.tilt, 0.0..=1.0, "");
        let mut idle = c.hide_idle_ms.is_some();
        if toggle_row(ui, "Hide when idle", &mut idle) {
            c.hide_idle_ms = idle.then_some(2000.0);
        }
        if let Some(ms) = &mut c.hide_idle_ms {
            slider(ui, "Idle after", ms, 500.0..=10_000.0, " ms");
        }
        let mut lp = c.loop_ms.is_some();
        if toggle_row(ui, "Loop position at end", &mut lp) {
            c.loop_ms = lp.then_some(1000.0);
        }
        if let Some(ms) = &mut c.loop_ms {
            slider(ui, "Loop over", ms, 300.0..=5000.0, " ms");
        }
        let mut freeze = c.freeze_ms > 0.0;
        if toggle_row(ui, "Freeze at end", &mut freeze) {
            c.freeze_ms = if freeze { 1000.0 } else { 0.0 };
        }
        if c.freeze_ms > 0.0 {
            slider(ui, "Freeze for", &mut c.freeze_ms, 200.0..=5000.0, " ms");
        }
    });
    section(ui, "Clicks", |ui| {
        let mut kind = match c.click_effect {
            ClickEffect::None => 0,
            ClickEffect::Circle => 1,
            ClickEffect::Ripple { .. } => 2,
        };
        if segmented(ui, &mut kind, &[(0, "None"), (1, "Circle"), (2, "Ripple")]) {
            c.click_effect = match kind {
                1 => ClickEffect::Circle,
                2 => ClickEffect::Ripple { strength: 2.0 },
                _ => ClickEffect::None,
            };
        }
        if let ClickEffect::Ripple { strength } = &mut c.click_effect {
            slider(ui, "Strength", strength, 0.5..=5.0, "");
        }
        toggle_row(ui, "Click sounds", &mut d.style.audio.click_sounds);
        if d.style.audio.click_sounds {
            slider(ui, "Click volume", &mut d.style.audio.click_volume, 0.0..=1.0, "");
        }
    });
}

fn camera(ui: &mut Ui, d: &mut Project, has: bool) {
    if !has {
        caption(ui, "Record with the camera on to add a camera bubble.");
        return;
    }
    let c = &mut d.style.camera;
    section(ui, "Camera", |ui| {
        toggle_row(ui, "Hide camera", &mut c.hide);
        widgets::camera_look(ui, c);
        if !c.shape.is_square() {
            row(ui, "Aspect", |ui| {
                segmented(ui, &mut c.aspect, &[(CameraAspect::Horizontal, "16:9"), (CameraAspect::Vertical, "9:16"), (CameraAspect::Square, "1:1"), (CameraAspect::Original, "Auto")]);
            });
        }
        slider(ui, "Size while zoomed", &mut c.zoom_scale, 0.3..=1.0, "×");
    });
    section(ui, "Fine position", |ui| {
        slider(ui, "Horizontal", &mut c.position.x, 0.0..=1.0, "");
        slider(ui, "Vertical", &mut c.position.y, 0.0..=1.0, "");
    });
}

fn captions(ui: &mut Ui, ed: &mut Editor, d: &mut Project) {
    section(ui, "Captions", |ui| {
        toggle_row(ui, "Show captions", &mut d.style.captions.show);
        slider(ui, "Size", &mut d.style.captions.size, 0.5..=2.0, "×");
        if ed.rec.transcript.is_empty() {
            caption(ui, "No transcript yet.");
            if ed.rec.meta.mic.is_some() {
                transcribe_controls(ui, ed);
            } else {
                caption(ui, "Record with the microphone to generate captions.");
            }
        } else {
            caption(ui, &format!("{} words — click a line to fix it", ed.rec.transcript.len()));
            ui.collapsing("Transcribe again", |ui| {
                caption(ui, "Replaces the current captions, including your edits.");
                transcribe_controls(ui, ed);
            });
            let lines = crate::engine::captions::lines(&ed.rec.transcript);
            let mut edited = None;
            for (i, line) in lines.iter().enumerate() {
                let id = ui.id().with(("caption-line", i, line.start.to_bits()));
                let mut buf = ui.data_mut(|d| d.get_temp::<String>(id)).unwrap_or_else(|| line.text());
                ui.horizontal(|ui| {
                    ui.label(RichText::new(widgets::fmt_time(line.start)).size(10.0).color(pal(ui).secondary).monospace());
                    let r = ui.add(egui::TextEdit::singleline(&mut buf).desired_width(f32::INFINITY).font(egui::FontId::proportional(12.0)));
                    if r.changed() {
                        ui.data_mut(|d| d.insert_temp(id, buf.clone()));
                    }
                    if r.lost_focus() {
                        ui.data_mut(|d| d.remove::<String>(id));
                        if buf != line.text() {
                            edited = Some((line.clone(), buf.clone()));
                        }
                    }
                });
            }
            if let Some((line, text)) = edited {
                let mut words = ed.rec.transcript.clone();
                crate::engine::captions::edit_line(&mut words, &line, &text);
                match crate::project::write_json(&crate::transcribe::transcript_path(&ed.package), &words) {
                    Ok(()) => {
                        ed.rec.transcript = words;
                        ed.preview.set_project(&ed.project, &ed.rec);
                    }
                    Err(e) => ed.status = Some(format!("Couldn't save captions: {e:#}")),
                }
            }
        }
    });
}

/// Engine picker and the Transcribe button (or progress while running).
fn transcribe_controls(ui: &mut Ui, ed: &mut Editor) {
    use crate::transcribe::Engine;
    use crate::whisper::Model;
    use std::sync::atomic::Ordering;
    if ed.transcribing.is_some() {
        let p = &ed.transcribe_progress;
        let pct = p.permille.load(Ordering::Relaxed) as f32 / 10.0;
        let text = match (ed.caption_engine, p.phase.load(Ordering::Relaxed)) {
            (Engine::Whisper(m), 0) if !m.is_downloaded() => format!("Downloading Whisper {}… {pct:.0}%", m.name()),
            (Engine::Whisper(_), _) => format!("Transcribing on device… {pct:.0}%"),
            (Engine::Apple, _) => "Transcribing on device…".into(),
        };
        ui.horizontal(|ui| {
            ui.spinner();
            caption(ui, &text);
        });
        ui.ctx().request_repaint_after(std::time::Duration::from_millis(250));
        return;
    }
    let mut whisper = matches!(ed.caption_engine, Engine::Whisper(_));
    row(ui, "Engine", |ui| {
        segmented(ui, &mut whisper, &[(true, "Whisper"), (false, "Apple")]);
    });
    match (whisper, ed.caption_engine) {
        (true, Engine::Apple) => ed.caption_engine = Engine::Whisper(crate::whisper::best_downloaded().unwrap_or(Model::Base)),
        (false, Engine::Whisper(_)) => ed.caption_engine = Engine::Apple,
        _ => {}
    }
    if let Engine::Whisper(mut model) = ed.caption_engine {
        let label = |m: Model| {
            if m.is_downloaded() { format!("{} (downloaded)", m.name()) } else { format!("{} ({} MB download)", m.name(), m.size_mb()) }
        };
        row(ui, "Model", |ui| {
            egui::ComboBox::from_id_salt("whisper-model").selected_text(label(model)).show_ui(ui, |ui| {
                for m in Model::ALL {
                    ui.selectable_value(&mut model, m, label(m));
                }
            });
        });
        ed.caption_engine = Engine::Whisper(model);
        caption(ui, "Runs on this Mac with Whisper. Larger models are more accurate but slower.");
    } else {
        caption(ui, "Uses Apple's on-device speech recognition (asks for Speech Recognition access).");
    }
    if ui.button("Transcribe microphone").clicked() {
        ed.start_transcription();
    }
}

fn audio(ui: &mut Ui, ed: &mut Editor, d: &mut Project) {
    let a = &mut d.style.audio;
    section(ui, "Audio", |ui| {
        slider(ui, "Volume", &mut a.volume, 0.0..=2.0, "");
        let peaks = *ed.peaks.lock().unwrap_or_else(|e| e.into_inner());
        let silent = |p: Option<f32>| peaks.is_some() && super::editor::TrackPeaks::silent(p);
        if ed.rec.meta.mic.is_some() {
            toggle_row(ui, "Mute microphone", &mut a.mute_mic);
            if silent(peaks.and_then(|p| p.mic)) {
                caption(ui, "The microphone only recorded silence.");
            }
            toggle_row(ui, "Enhance voice", &mut a.enhance_mic);
            if a.enhance_mic {
                caption(ui, "On-device voice isolation removes background noise.");
            }
        } else if ed.rec.meta.system_audio.is_some() {
            caption(ui, "The microphone was off for this recording (turn it on in the Record options next time).");
        }
        if ed.rec.meta.system_audio.is_some() {
            toggle_row(ui, "Mute system audio", &mut a.mute_system);
            if silent(peaks.and_then(|p| p.system)) {
                caption(ui, "System audio is silent: nothing played that ScreenCaptureKit could capture (sounds from command-line tools aren't).");
            }
        }
        if ed.rec.meta.mic.is_none() && ed.rec.meta.system_audio.is_none() {
            caption(ui, "This recording has no audio.");
        }
    });
    section(ui, "Background music", |ui| {
        ui.horizontal(|ui| {
            if ui.button("Choose…").clicked()
                && let Some(f) = rfd::FileDialog::new().add_filter("Audio", &["mp3", "m4a", "wav", "aac", "aiff"]).pick_file()
            {
                a.music = Some(f.to_string_lossy().into_owned());
            }
            if a.music.is_some() && ui.button("Remove").clicked() {
                a.music = None;
            }
        });
        if let Some(m) = &a.music {
            caption(ui, &std::path::Path::new(m).file_name().map(|n| n.to_string_lossy().into_owned()).unwrap_or_default());
            slider(ui, "Music volume", &mut a.music_volume, 0.0..=1.0, "");
        }
    });
    section(ui, "Voice-over", |ui| {
        match ed.voice.as_ref().map(|v| v.elapsed()) {
            Some(elapsed) => {
                ui.horizontal(|ui| {
                    let (rect, _) = ui.allocate_exact_size(vec2(10.0, 10.0), egui::Sense::hover());
                    ui.painter().circle_filled(rect.center(), 5.0, Color32::from_rgb(255, 59, 48));
                    ui.label(format!("Recording {elapsed:.1} s"));
                    if ui.button("Stop").clicked() {
                        ed.deferred = Some(Deferred::StopVoice);
                    }
                });
            }
            None => {
                if ui.button("Record from playhead").on_hover_text("Narrate over the video; the preview plays silently").clicked() {
                    ed.deferred = Some(Deferred::StartVoice);
                }
                if crate::capture::camera::builtin_mic_off(None) {
                    caption(ui, "The lid is closed, so the built-in microphone only records silence. Pick another input in System Settings › Sound.");
                }
            }
        }
        if !d.timeline.voiceovers.is_empty() {
            toggle_row(ui, "Lower recorded audio", &mut d.style.audio.duck_under_voiceover);
            if d.style.audio.duck_under_voiceover {
                slider(ui, "Level under voice", &mut d.style.audio.duck_level, 0.0..=1.0, "");
            }
            let mut remove = None;
            for vo in &mut d.timeline.voiceovers {
                ui.horizontal(|ui| {
                    caption(ui, &format!("{} · {:.1} s", widgets::fmt_time(vo.start), vo.duration / 1000.0));
                    ui.add(egui::Slider::new(&mut vo.volume, 0.0..=2.0).show_value(false));
                    if ui.small_button("Delete").clicked() {
                        remove = Some(vo.id);
                    }
                });
            }
            if let Some(id) = remove {
                d.timeline.voiceovers.retain(|v| v.id != id);
            }
        }
    });
}

fn shortcuts(ui: &mut Ui, d: &mut Project, keys: usize) {
    let s = &mut d.style.shortcuts;
    section(ui, "Keyboard shortcuts", |ui| {
        toggle_row(ui, "Show shortcuts", &mut s.show);
        toggle_row(ui, "Include single keys", &mut s.single_keys);
        slider(ui, "Size", &mut s.size, 0.5..=2.0, "×");
        if keys == 0 {
            caption(ui, "No key presses were recorded. Grant Glide Input Monitoring in System Settings › Privacy & Security to capture them.");
        } else {
            caption(ui, &format!("{keys} key events recorded"));
        }
    });
}

fn animation(ui: &mut Ui, ed: &mut Editor, d: &mut Project) {
    section(ui, "Zoom animation", |ui| {
        let mut cfg = Some(d.style.screen_spring);
        spring_picker(ui, "Style", &mut cfg, &[("Focused", Some(SpringConfig::SCREEN_FOCUSED)), ("Smooth", Some(SpringConfig::SCREEN_SMOOTH))]);
        if let Some(c) = cfg {
            d.style.screen_spring = c;
        }
    });
    section(ui, "Motion blur", |ui| {
        let m = &mut d.style.motion_blur;
        slider(ui, "Amount", &mut m.amount, 0.0..=1.0, "");
        egui::CollapsingHeader::new("Advanced").show(ui, |ui| {
            slider(ui, "Cursor", &mut m.cursor, 0.0..=1.0, "");
            slider(ui, "Screen movement", &mut m.screen_move, 0.0..=1.0, "");
            slider(ui, "Zoom", &mut m.screen_zoom, 0.0..=1.0, "");
        });
    });
    section(ui, "Automatic zooms", |ui| {
        slider(ui, "Default zoom", &mut d.style.default_zoom, 1.2..=4.0, "×");
        if ui.button("Regenerate from clicks").clicked() {
            let events = crate::engine::events::Events::new(ed.rec.mouse.clone());
            let zooms = crate::engine::zoom::auto_zooms(&events.downs, ed.rec.meta.duration_ms, d.style.default_zoom, &mut d.timeline);
            d.timeline.zooms = zooms;
        }
        let n = d.timeline.zooms.len();
        caption(ui, &format!("{n} zoom{}", if n == 1 { "" } else { "s" }));
    });
    section(ui, "Typing", |ui| {
        let runs = crate::engine::typing::ranges(&ed.rec.keys);
        if runs.is_empty() {
            caption(ui, if ed.rec.keys.is_empty() { "No key presses were recorded." } else { "No typing sections found." });
            return;
        }
        let secs: f64 = runs.iter().map(|(s, e)| e - s).sum::<f64>() / 1000.0;
        caption(ui, &format!("{} typing section{} ({secs:.1} s). Speed them up:", runs.len(), if runs.len() == 1 { "" } else { "s" }));
        ui.horizontal(|ui| {
            for speed in [2.0, 3.0, 4.0] {
                if ui.button(format!("{speed}×")).clicked() {
                    let n = crate::engine::typing::speed_up(&mut d.timeline, &runs, speed);
                    ed.status = Some(format!("Sped up {n} typing section{} to {speed}×", if n == 1 { "" } else { "s" }));
                }
            }
        });
    });
}

fn zoom_panel(ui: &mut Ui, ed: &mut Editor, d: &mut Project, id: u64) {
    let Some(z) = d.timeline.zooms.iter_mut().find(|z| z.id == id) else { return };
    let mut delete = false;
    section(ui, "Zoom", |ui| {
        slider(ui, "Zoom level", &mut z.scale, 1.0..=5.0, "×");
        let mut mode = match z.mode {
            ZoomMode::Auto => 0,
            ZoomMode::Manual { .. } => 1,
            ZoomMode::FollowMouse => 2,
        };
        if segmented(ui, &mut mode, &[(0, "Auto"), (1, "Manual"), (2, "Follow mouse")]) {
            z.mode = match mode {
                1 => ZoomMode::Manual { target: v2(0.5, 0.5) },
                2 => ZoomMode::FollowMouse,
                _ => ZoomMode::Auto,
            };
        }
        if let ZoomMode::Manual { target } = &mut z.mode {
            caption(ui, "Click the preview to choose where to zoom.");
            slider(ui, "X", &mut target.x, 0.0..=1.0, "");
            slider(ui, "Y", &mut target.y, 0.0..=1.0, "");
        } else {
            slider(ui, "Edge snapping", &mut z.snap_edges, 0.0..=0.5, "");
        }
        toggle_row(ui, "Instant (no animation)", &mut z.instant);
        toggle_row(ui, "Disabled", &mut z.disabled);
        caption(ui, &format!("{} – {}", widgets::fmt_time(z.start), widgets::fmt_time(z.end)));
        delete = ui.button("Delete zoom").clicked();
    });
    if delete {
        d.timeline.zooms.retain(|z| z.id != id);
        ed.selection = Selection::None;
    }
    if ui.button("Done").clicked() {
        ed.selection = Selection::None;
    }
}

fn slice_panel(ui: &mut Ui, d: &mut Project, id: u64) {
    let Some(s) = d.timeline.slices.iter_mut().find(|s| s.id == id) else { return };
    section(ui, "Clip", |ui| {
        ui.label("Speed");
        ui.horizontal_wrapped(|ui| {
            for sp in [0.25, 0.5, 0.75, 1.0, 1.25, 1.5, 2.0, 3.0, 4.0, 8.0] {
                if ui.selectable_label((s.speed - sp).abs() < 1e-6, format!("{sp}×")).clicked() {
                    s.speed = sp;
                }
            }
        });
        slider(ui, "Mic volume", &mut s.mic_volume, 0.0..=2.0, "");
        slider(ui, "System volume", &mut s.system_volume, 0.0..=2.0, "");
        toggle_row(ui, "Hide cursor", &mut s.hide_cursor);
        toggle_row(ui, "Raw cursor movement", &mut s.no_smoothing);
        caption(ui, &format!("Source {} – {}", widgets::fmt_time(s.start), widgets::fmt_time(s.end)));
    });
}

fn layout_panel(ui: &mut Ui, d: &mut Project, id: u64) {
    let Some(l) = d.timeline.layouts.iter_mut().find(|l| l.id == id) else { return };
    section(ui, "Camera layout", |ui| {
        segmented(ui, &mut l.kind, &[(LayoutKind::Both, "Both"), (LayoutKind::ScreenOnly, "Screen"), (LayoutKind::CameraOnly, "Camera")]);
        if l.kind == LayoutKind::Both {
            let mut size = l.camera_size.unwrap_or(0.35);
            if slider(ui, "Camera size", &mut size, 0.1..=0.8, "") {
                l.camera_size = Some(size);
            }
        }
    });
}

fn mask_panel(ui: &mut Ui, ed: &mut Editor, d: &mut Project, id: u64) {
    use crate::project::model::{Mask, MaskKind};
    let Some(m) = d.timeline.masks.iter_mut().find(|m| m.id == id) else { return };
    let mut delete = false;
    section(ui, "Mask", |ui| {
        let before = m.kind;
        segmented(ui, &mut m.kind, &[(MaskKind::Blur, "Blur"), (MaskKind::Pixelate, "Pixelate"), (MaskKind::Highlight, "Highlight")]);
        if m.kind != before {
            m.amount = Mask::default_amount(m.kind);
        }
        match m.kind {
            MaskKind::Blur => slider(ui, "Blur", &mut m.amount, 2.0..=60.0, " px"),
            MaskKind::Pixelate => slider(ui, "Pixel size", &mut m.amount, 4.0..=60.0, " px"),
            MaskKind::Highlight => slider(ui, "Dim", &mut m.amount, 0.1..=0.95, ""),
        };
        slider(ui, "Roundness", &mut m.radius, 0.0..=60.0, " px");
        caption(ui, "Drag on the preview to draw the region; drag inside it to move.");
        egui::CollapsingHeader::new("Position").show(ui, |ui| {
            slider(ui, "Left", &mut m.rect.x, 0.0..=1.0, "");
            slider(ui, "Top", &mut m.rect.y, 0.0..=1.0, "");
            slider(ui, "Width", &mut m.rect.w, 0.01..=1.0, "");
            slider(ui, "Height", &mut m.rect.h, 0.01..=1.0, "");
        });
        caption(ui, &format!("{} – {}", widgets::fmt_time(m.start), widgets::fmt_time(m.end)));
        ui.horizontal(|ui| {
            if ui.button("Delete mask").clicked() {
                delete = true;
            }
            if ui.button("Done").clicked() {
                ed.selection = Selection::None;
            }
        });
    });
    if delete {
        d.timeline.masks.retain(|m| m.id != id);
        ed.selection = Selection::None;
    }
}
